/* `:host` as well as `:root`.

     The document editor renders this stylesheet inside a shadow root, and in a
     shadow tree `:root` matches nothing — it means the document element, which
     is outside the boundary. So every token declared here was absent in the
     editor, and custom properties inherit through a shadow boundary, which
     meant the *app's* tokens took their place: the header rule vanished
     because nothing defines `--rule` out there, and the hairlines came out the
     app's pale blue instead of a mix of this document's ink.
     `:host` is the shadow root's own host and matches nothing in a plain
     document, so one rule serves both. */
  :root,
  :host {
      --doc-title: 20pt;
      --doc-lead: 11.5pt;
      --doc-h1: 14pt;
      --doc-h2: 12pt;
      --doc-h3: 11pt;
      --doc-body: 10.5pt;
      --doc-table: 9.5pt;
      --doc-caption: 9pt;
      --doc-note: 9pt;
      --doc-small: 9pt;
      --doc-kpi: 20pt;
      --doc-kpiLabel: 9pt;
      --doc-sectionNumber: 10.5pt;
      --doc-pageNumber: 9pt;
      --doc-leading-title: 1.25;
      --doc-leading-heading: 1.35;
      --doc-leading-body: 1.6;
      --doc-leading-table: 1.45;
      --doc-leading-note: 1.5;
      --accent: #5b5bd6;
      --ink: #1a1a1a;
      --muted: #666666;
      --font-body: 'Pretendard', 'Malgun Gothic', 'Apple SD Gothic Neo', sans-serif;
      --font-head: var(--font-body);
      --font-num: var(--font-head);
    --paper: #ffffff;
    /* Every neutral is a mix of the design system's ink; there is no grey
       literal anywhere in this file. A hairline, a border and the wash the
       paper floats on are one colour at three strengths. */
    --hair: color-mix(in srgb, var(--ink) 10%, transparent);
    --border: color-mix(in srgb, var(--ink) 14%, transparent);
    --wash: color-mix(in srgb, var(--ink) 5%, #fff);
    /* The one weakened accent: 2px of it under a table head reads as a rule
       rather than as a second heading. */
    --rule: color-mix(in srgb, var(--accent) 40%, transparent);

    /* ── 강조의 세 단계 ────────────────────────────────────────────────
       하나의 accent 에서 나온다. 서식이 자기 색을 따로 정하면 표지 띠도
       패널도 같이 따라가고, 정하지 않으면 셋 다 기본 accent 의 농담이 된다 —
       색을 세 군데에 적어 두면 프로젝트 색을 바꾼 사람이 표지만 바뀌고 패널은
       그대로인 문서를 받게 된다. */
    --accent-deep: color-mix(in srgb, var(--accent) 68%, #000);
    --accent-wash: color-mix(in srgb, var(--accent) 8%, #fff);
    --accent-band: linear-gradient(135deg, var(--accent) 0%, var(--accent-deep) 100%);

    /* ── 뜻이 있는 색 ──────────────────────────────────────────────────
       위의 셋과 달리 이것들은 토큰이 아니다. 기준을 넘겼다는 표시를 브랜드
       색으로 칠하면 넘겼다는 뜻이 사라지고 그냥 예쁜 숫자가 된다. 초록·주황·
       빨강은 취향이 아니라 약속이고, 약속은 프로젝트마다 달라지면 안 된다.
       한 서식이 정말로 다른 색을 써야 한다면 자기 `design.css` 에서 덮는다. */
    --positive: #12805c;
    --caution: #a86a00;
    --negative: #b42318;
  }
  *, *::before, *::after { box-sizing: border-box; }
  html, body { margin: 0; padding: 0; }
  body {
    /* The paper is white and the window is not, so the page floats. */
    background: var(--wash);
    color: var(--ink);
    font-family: var(--font-body);
    font-size: var(--doc-body);
    line-height: var(--doc-leading-body);
    -webkit-font-smoothing: antialiased;
  }
  /* Korean breaks between syllables unless it is told not to, which puts the
     second half of a word on the next line. `keep-all` moves the break to a
     space; `break-word` is the escape hatch for a token with no space in it,
     such as a path or an identifier. */
  body { word-break: keep-all; overflow-wrap: break-word; }
  .page {
    /* 34rem of text + 2rem of gutter + 9rem of margin column + the padding. */
    max-width: 52rem;
    margin: 0 auto;
    padding: 0 3.5rem 6rem;
    background: var(--paper);
    min-height: var(--page-h, 100vh);
    counter-reset: sec;
  }

  /* ── cover ─────────────────────────────────────────────────────────
     A page of its own. The title block sits on the one-third line, the facts
     of the review sit under it, and the accent rule waits at the foot of the
     page rather than under the title — the reader's eye is meant to arrive at
     the title, not be stopped there. */
  .cover {
    display: flex;
    flex-direction: column;
    /* Padding, content and the margin below add up to exactly one sheet, so on the
       editor's continuous page the second sheet starts with the first section rather
       than with the tail of the cover. Print measures the cover in millimetres below. */
    min-height: calc(var(--page-h, 100vh) * 0.68 - 5.6rem);
    padding: calc(var(--page-h, 100vh) * 0.32) 0 2.2rem;
    margin: 0 0 3.4rem;
    /* Paged.js does not read the print block below; the cover ends its page here too. */
    break-after: page;
  }
  .cover h1 {
    margin: 0 0 0.9rem;
    max-width: 22ch;
    font-size: var(--doc-title);
    font-weight: 650;
    line-height: var(--doc-leading-title);
    letter-spacing: -0.02em;
    text-wrap: balance;
  }
  /* `.lead` is what the exporters read, but a cover paragraph is the lead
     whether or not the model remembered to say so. */
  .cover .lead, .cover > p {
    margin: 0 0 2.6rem;
    max-width: 52ch;
    color: var(--muted);
    font-size: var(--doc-lead);
    line-height: 1.65;
  }
  /* 목적 · 독자 · 기간 · 작성. Two columns, because a reader scans the left
     one and reads the right one. */
  .cover dl {
    display: grid;
    grid-template-columns: 5.5rem minmax(0, 1fr);
    gap: 0.4rem 1.2rem;
    margin: 0;
    max-width: 30rem;
    font-size: var(--doc-small);
    line-height: 1.6;
  }
  .cover dt { color: var(--muted); font-weight: 600; }
  .cover dd { margin: 0; max-width: none; color: var(--ink); font-size: inherit; }
  .cover::after {
    content: "";
    display: block;
    margin-top: auto;
    height: 3px;
    background: var(--accent);
  }

  /* ── 채워진 표지 ────────────────────────────────────────────────────
     같은 표지의 다른 얼굴. 흰 종이 위 제목 대신, 색이 깔린 띠 위에 흰 글씨가
     앉는다 — 첫 장을 넘기기 전에 이것이 어느 조직의 무슨 문서인지 말하는 방식
     이고, 인쇄된 표지가 실제로 하는 일이다.

     서식이 `[wrap] cover` 에 `class="cover filled"` 를 적어 켠다. 여기 두는
     이유는 색이 accent 에서 나오기 때문이다: 서식마다 그라데이션을 다시 적으면
     프로젝트 색을 바꾼 사람이 표지만 옛 색인 문서를 받는다.

     쪽 전체가 아니라 띠다. A4 한 장을 통째로 칠하면 인쇄에서 잉크가 그만큼
     들고, 흑백으로 뽑으면 제목이 회색 판 위의 흰 글씨가 되어 읽히지 않는다. */
  .cover.filled {
    min-height: 0;
    padding: 3.2rem 2.4rem 2.6rem;
    margin: 0 0 2.8rem;
    background: var(--accent-band);
    color: #fff;
    border-radius: 4px;
  }
  .cover.filled h1 { color: #fff; }
  .cover.filled .lead,
  .cover.filled > p { color: rgba(255, 255, 255, 0.86); margin-bottom: 1.6rem; }
  .cover.filled dt { color: rgba(255, 255, 255, 0.7); }
  .cover.filled dd { color: #fff; }
  /* 아래 규칙이 그리는 accent 막대는 색 위의 색이라 보이지 않는다. */
  .cover.filled::after { display: none; }
  @media print {
    /* 배경을 지우는 프린터가 있고, 그러면 흰 글씨만 남아 표지가 백지가 된다.
       인쇄에서는 색을 글자 쪽으로 옮긴다 — 같은 위계, 다른 방법. */
    .cover.filled {
      background: none; color: var(--ink);
      border-left: 4px solid var(--accent);
      border-radius: 0;
      padding-left: 1.2rem;
    }
    .cover.filled h1 { color: var(--accent); }
    .cover.filled .lead,
    .cover.filled > p { color: var(--muted); }
    .cover.filled dt { color: var(--muted); }
    .cover.filled dd { color: var(--ink); }
  }

  /* ── a section: text column, and the column beside it ──────────────
     Auto-placement does the alignment. Everything is pinned to column 1, so
     the placement cursor walks down that column; a `<small>` asks for column 2
     and lands on the row the cursor is already on — the row of the paragraph
     it follows. Write the note after the sentence it answers for, and it
     appears beside that sentence. */
  /* 한 열이다. 오른쪽 9rem 을 주석 열로 비워 두던 조판이었는데, 그 열은 거의
     늘 비어 있었고 — 모델이 여백 주석을 쓰는 일이 드물다 — 비어 있는 동안에는
     본문이 종이의 3분의 2만 쓰는 것으로만 보였다. 근거는 각주로 내린다. 아래
     `small` 을 보라. */
  section {
    display: flex;
    flex-direction: column;
    margin: 0 0 2.6rem;
    counter-reset: note;
  }
  section > * { min-width: 0; }
  h2 {
    margin: 0 0 0.9rem;
    font-size: var(--doc-h1);
    font-weight: 650;
    line-height: var(--doc-leading-heading);
    letter-spacing: -0.01em;
    text-wrap: balance;
  }
  /* The section number is inline, in the accent, and smaller than the words it
     numbers — a label, not a headline. No box and no bar: an accent bar down
     the left of every heading is the default this template exists without. */
  h2 { counter-increment: sec; }
  h2::before {
    content: counter(sec) ".";
    margin-right: 0.5rem;
    color: var(--accent);
    font-size: var(--doc-sectionNumber);
    font-weight: 650;
    font-variant-numeric: tabular-nums;
    letter-spacing: 0;
  }
  /* In the paged preview Paged.js clones `.page` onto every sheet, so the CSS counter
     restarts per page; it also writes each heading's running number into
     `data-counter-sec-value`, which is the one to show there. */
  .pagedjs_page h2[data-counter-sec-value]::before { content: attr(data-counter-sec-value) "."; }
  /* Ink rather than muted: a sub-heading fainter than its own paragraph reads
     as a caption somebody left behind. */
  h3 {
    margin: 1.7rem 0 0.4rem;
    font-size: var(--doc-h2);
    font-weight: 650;
    color: var(--ink);
    text-wrap: balance; line-height: var(--doc-leading-heading); }
  /* One step under `h3`, and the last one. The editor's heading picker offers
     it and the sanitiser now keeps it, so it needs a rule of its own — without
     one it lands at the browser's `h4`, which is smaller than the paragraph
     under it and reads as a mistake. */
  h4 {
    margin: 1.2rem 0 0.3rem;
    font-size: var(--doc-h3);
    font-weight: 650;
    color: var(--ink);
    text-wrap: balance; line-height: var(--doc-leading-heading); }
  /* Not justified. Korean with `keep-all` breaks at spaces, so justifying
     stretches the few spaces a line has into rivers down the page. */
  p { margin: 0 0 0.95rem; text-wrap: pretty; }
  ul, ol { margin: 0 0 1.05rem; padding-left: 1.25rem; }
  li { margin: 0 0 0.35rem; }
  li::marker { color: var(--accent); }
  blockquote {
    margin: 1.3rem 0;
    padding: 0.1rem 0 0.1rem 1.1rem;
    border-left: 1px solid var(--hair);
    color: var(--muted);
  }
  table {
    width: 100%;
    border-collapse: collapse;
    margin: 1.1rem 0 1.2rem;
    font-size: var(--doc-table);
    line-height: var(--doc-leading-table);
  }
  th {
    padding: 0.4em 0.7em 0.4em 0;
    border-bottom: 2px solid var(--rule);
    color: var(--muted);
    font-weight: 600;
    font-size: var(--doc-small);
    letter-spacing: 0.04em;
    text-align: left;
  }
  td {
    padding: 0.5em 0.7em 0.5em 0;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: top;
    font-variant-numeric: tabular-nums;
  }

  /* ── the subordinate voice ─────────────────────────────────────────
     One size, one colour, one measure, everywhere in the catalogue: 0.84em,
     line-height 1.55, `--muted`, at most 54ch, never italic, half a rem below
     the thing it explains. Here it also decides which column it lives in. */
  small, figcaption, dd {
    color: var(--muted);
    font-size: var(--doc-small);
    line-height: 1.55;
    font-style: normal;
    max-width: 54ch;
  }
  /* `*`, `**`, `***` — 하나짜리 기호를 되풀이하는 `symbolic` 이라 번호가 몇 개든
     같은 규칙으로 늘어난다. 붙이는 쪽은 조판이고, 본문의 `<sup>` 은 모델이 쓴다.
     세는 것을 조판이 맡는 이유는, 절 하나를 지우거나 순서를 바꿔도 각주 번호가
     저절로 다시 매겨져야 하기 때문이다. */
  @counter-style footnote-mark { system: symbolic; symbols: "*"; suffix: ""; }

  /* 본문 안의 참조 표시. */
  sup {
    font-size: 0.72em;
    line-height: 1;
    vertical-align: super;
    color: var(--accent);
    margin-left: 0.1em;
  }

  /* 각주. `order` 로 절의 맨 아래에 모인다 — 설명하는 문단 바로 뒤에 쓰여도
     읽을 때는 발치에 모여 있고, 그것이 여백 주석과 각주의 차이다. 문서 순서는
     그대로이므로 번호도 쓴 순서대로 붙는다. */
  section > small,
  section > figcaption {
    order: 1;
    display: block;
    max-width: 46rem;
    margin: 0;
    padding: 0 0 0 1.4rem;
    text-indent: -1.4rem;
    font-size: 0.83rem;
    line-height: 1.6;
    color: var(--muted);
  }
  section > small { counter-increment: note; }
  section > small::before {
    content: counter(note, footnote-mark) " ";
    color: var(--accent);
    font-weight: 650;
  }
  /* 각주 무리와 본문 사이의 선. 첫 각주에만 붙으므로 개수와 무관하다. */
  section > small:first-of-type {
    margin-top: 1.1rem;
    padding-top: 0.6rem;
    border-top: 1px solid var(--hair);
  }
  dl { margin: 0 0 1.1rem; }
  dt { font-weight: 650; }
  dd { margin: 0 0 0.6rem; }
  hr { border: 0; border-top: 1px solid var(--border); margin: 1.6rem 0; }
  /* A line of code is a quotation from a machine, so it has to survive being
     copied out of the page character for character: a fixed-width face, and a
     field that shows where it starts and where it stops. Inline only — `pre`
     is not in the vocabulary, so nothing here can grow into a wall. */
  code {
    font-family: var(--font-mono, ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace);
    font-size: 0.88em;
    padding: 0.05em 0.32em;
    background: var(--wash);
    border: 1px solid var(--border);
    border-radius: 3px;
    overflow-wrap: anywhere;
  }
  /* A picture is a data URI the server embedded; nothing here fetches from
     outside a sandboxed artifact. */
  /* 차트. figure 가 그림이 아니라 **숫자**를 들고 있다 — 그려진 것은 누구나
     다시 그릴 수 있고, 문서인 것은 값이다. 화면은 페이지뷰에서 비어 있고
     웹뷰와 내보낸 파일이 같은 숫자에서 각자 그린다. */
  figure.chart { margin: 1.3rem 0; break-inside: avoid; }
  figure.chart:empty::after {
    content: "차트 — 웹뷰에서 보입니다";
    display: block; padding: 1.2rem;
    border: 1px dashed var(--rule); border-radius: 2px;
    text-align: center; font-size: 0.72rem; color: var(--muted);
  }

  /* 도해·차트. 브라우저가 그려 그림으로 보관하고, 원본은 figure 가 들고 있다 —
     한 글자만 고쳐도 그림이 통째로 사라지던 자리다. */
  figure.diagram { margin: 1.3rem 0; text-align: center; break-inside: avoid; }
  figure.diagram img { max-width: 100%; height: auto; }
  /* 아직 아무도 열어 보지 않아 그림이 없는 도해. 빈 자리를 남겨 두면 종이에
     구멍이 난 것처럼 보이므로, 무엇이 올 자리인지 말해 준다. */
  figure.diagram:empty::after {
    content: "도해 — 웹뷰에서 한 번 열면 그려집니다";
    display: block; padding: 1.2rem;
    border: 1px dashed var(--rule); border-radius: 2px;
    font-size: 0.72rem; color: var(--muted);
  }

  /* 절차. `report_export._kpi_rows`가 같은 블록을 파일에서 표로 그린다.
     그림이 아니라 글로 남는다 — 받은 사람이 한 단계를 고치거나 찾을 수 있다. */
  ol.steps {
    list-style: none; counter-reset: step;
    margin: 1.2rem 0; padding: 0 0 0 0;
    border-left: 2px solid var(--accent);
    break-inside: avoid;
  }
  ol.steps > li {
    counter-increment: step;
    display: flex; gap: 0.6rem; align-items: baseline;
    margin: 0; padding: 0.4rem 0 0.4rem 0.75rem;
    border-bottom: 1px solid var(--rule);
  }
  ol.steps > li:last-child { border-bottom: 0; }
  ol.steps > li::before {
    content: counter(step);
    flex: 0 0 auto; min-width: 1.1em;
    font-family: var(--font-head); font-weight: 600;
    color: var(--accent); font-variant-numeric: tabular-nums;
  }
  ol.steps > li span { color: var(--muted); }

  /* 강조 수치. `report_export._kpi_rows`가 같은 블록을 파일에서 표로 그린다.
     서식이 크기와 색을 모두 쥐고, 모델은 숫자와 이름만 쓴다 — 살균기가
     모델의 `style=`은 지우고 `class`는 남기는 이유가 이것이다. */
  .kpi {
    display: flex; flex-wrap: wrap; gap: 0.6rem 1.4rem;
    justify-content: space-around;
    margin: 1.3rem 0; padding: 0.75rem 0;
    border-top: 1px solid var(--rule); border-bottom: 1px solid var(--rule);
    break-inside: avoid;
  }
  .kpi > div { flex: 1 1 0; min-width: 5.5rem; text-align: center; }
  .kpi strong {
    display: block; font-family: var(--font-num);
    font-size: var(--doc-kpi); line-height: 1.15; color: var(--accent);
    font-variant-numeric: tabular-nums;
  }
  .kpi span {
    display: block; margin-top: 0.2rem;
    font-size: var(--doc-kpiLabel); color: var(--muted); letter-spacing: 0.01em;
  }
  /* 카드 격자. `report_export._cards`가 같은 블록을 세 파일 형식에서 두 단
     표로 그린다. 읽는 사람이 훑는 대목 — 산출물 옆에 목표, 이해관계자 옆에
     성공 기준 — 을 줄글로 늘어놓으면 결국 머릿속에서 이 격자를 다시 그리게
     된다. 서식이 칸과 색을 쥐고 모델은 제목과 줄만 쓴다. */
  .cards {
    display: grid; grid-template-columns: 1fr 1fr; gap: 0.9rem;
    margin: 1.4rem 0; break-inside: avoid;
  }
  .cards > div {
    border: 1px solid var(--rule); border-radius: 3px;
    padding: 0.85rem 0.95rem 0.9rem;
    break-inside: avoid;
  }
  /* 제목 앞의 짧은 색 막대. 카드가 넷이면 넷 다 같은 무게로 읽히고, 그러면
     격자가 아니라 상자 넷이 된다 — 막대는 어디부터가 한 칸인지 말한다. */
  .cards > div > :first-child::before {
    content: ""; display: block;
    width: 1.6rem; height: 0.28rem; margin-bottom: 0.5rem;
    background: var(--accent);
  }
  /* 카드마다 다른 띠. 넷이 모두 같은 색이면 띠는 장식이 되고, 다르면 "이건
     저것과 다른 갈래" 라는 말을 한다 — 격자에서 눈이 자리를 잡는 방식이다.
     accent 에서 나온 농담이므로 브랜드 색을 바꾸면 넷이 함께 움직인다. */
  .cards > div:nth-child(2) > :first-child::before {
    background: var(--accent-deep);
  }
  .cards > div:nth-child(3) > :first-child::before {
    background: color-mix(in srgb, var(--accent) 55%, var(--ink));
  }
  .cards > div:nth-child(4) > :first-child::before {
    background: color-mix(in srgb, var(--accent) 45%, #fff);
  }
  .cards h3, .cards h4 {
    margin: 0 0 0.45rem; font-size: 0.98rem; line-height: 1.35;
  }
  .cards ul, .cards ol { margin: 0; padding-left: 1.05rem; }
  .cards li { margin: 0 0 0.3rem; font-size: 0.9rem; line-height: 1.5; }
  .cards p { margin: 0 0 0.4rem; font-size: 0.9rem; }
  .cards > div > :last-child { margin-bottom: 0; }

  /* 지나치면 안 되는 한 대목. 상자가 아니라 왼쪽 막대다 — 상자는 위의 카드와
     표까지 상자여서 하나 더 그리면 무엇이 강조인지 알 수 없게 된다. */
  .callout {
    display: block; margin: 1.3rem 0;
    padding: 0.15rem 0 0.15rem 0.95rem;
    border-left: 3px solid var(--accent);
    break-inside: avoid;
  }
  .callout h3, .callout h4 {
    margin: 0 0 0.3rem; font-size: 1rem; color: var(--accent);
  }
  .callout p { margin: 0 0 0.35rem; }
  .callout > :last-child { margin-bottom: 0; }

  /* 한 단으로 접힌다. 두 단을 폭 360px 에 밀어 넣으면 카드마다 한 줄에 두세
     글자가 되고, 그건 격자가 아니라 세로로 긴 글자 기둥 둘이다. */
  @media screen and (max-width: 620px) {
    .cards { grid-template-columns: 1fr; }
  }

  figure { margin: 1.3rem 0; break-inside: avoid; }
  /* A page scrolls, so width is the constraint — but a picture taller than the
     paper still breaks across two pages with nothing on the second. */
  figure img { display: block; max-width: 100%; max-height: calc(var(--page-h, 100vh) * 0.6); width: auto; height: auto; }
  figcaption { margin-top: 0.5rem; }

  /* ── narrow ────────────────────────────────────────────────────────
     There is no margin to write in on a phone, so the note becomes an indented
     annotation directly under its paragraph. Same voice, same distance from
     what it explains; only the direction changes.

     `screen and` is load-bearing. A width query is evaluated against the page
     box when printing, and A4 is 794px — without it, printing a report took
     this branch and the margin column, the whole point of the shape, collapsed
     on exactly the output the shape is for. */
  @media screen and (max-width: 900px) {
    .page { padding: 0 1.4rem 4rem; }
    .cover { padding-top: calc(var(--page-h, 100vh) * 0.22); }
  }

  @page { size: A4 portrait; margin: 20mm 18mm; }
  @media print {
    html { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
    body { background: #fff; }
    .page { max-width: none; margin: 0; padding: 0; min-height: 0; }
    /* `vh` is the page box on paper, so the cover is measured in millimetres
       instead: a third of the way down A4, with the accent rule at the foot. */
    .cover {
      min-height: 232mm;
      padding: 74mm 0 0;
      margin: 0;
      page-break-after: always;
      break-after: page;
    }
    section { margin: 0 0 12mm; }
    /* 발치의 문서 이름. 인쇄된 두 번째 장부터는 이 종이가 무엇의 일부인지
       종이 자신이 말해야 한다 — 회의 탁자 위에서 낱장은 반드시 흩어진다.
       Chromium 은 @page 여백 상자를 그리지 않으므로 fixed 로 반복한다. */
    .doc-foot {
      display: block;
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      padding: 2mm 0 0;
      border-top: 1px solid var(--hair);
      color: var(--muted);
      font-size: 8pt;
      letter-spacing: 0.03em;
    }
    /* 각주는 자기 절과 같은 쪽에 있어야 뜻이 있다. */
    section > small { break-inside: avoid; break-before: avoid; }
    h2 { page-break-after: avoid; break-after: avoid; }
    table, figure, blockquote { break-inside: avoid; }
  }

  /* ── 편집기 ─────────────────────────────────────────────────────────
     이 시트는 두 곳에서 읽힌다. 완성된 파일 — sandbox 프레임과 내려받은
     .html — 과, 문서 편집기. 편집기에서는 절의 본문이 이렇게 감싸인다:

         <section>
           <h2>…</h2>                     서식이 그리는 절 제목
           <div class="doc-body">         편집기가 만드는 칸
             <div class="ProseMirror">    ProseMirror 가 재는 요소
               <p>…</p> <table>…</table>  사람이 치는 것

     세 가지를 여기서 맞춘다. 완성된 파일에는 이 구조가 없으므로 블록 전체가
     그쪽에서는 무해하다.

     1. **선택자가 두 단계 어긋난다.** `section > *` 는 `.doc-body` 를 가리키고
        본문은 놓친다. 경계를 넘는 규칙만 아래에서 다시 선언한다 — 원본은
        고치지 않고 더한다. 같은 시트가 래퍼 없는 파일도 그려야 하므로.
     2. **상자가 두 개 더 생긴다.** `.doc-body` 는 `display: contents` 로
        없앤다. `.ProseMirror` 는 없애면 **안 된다** — 상자를 만들지 않는
        요소는 `getBoundingClientRect()` 가 빈 사각형을 돌려주고, ProseMirror
        는 그 사각형으로 클릭 위치를 글자 위치로 옮긴다. 없애면 서식은 맞는데
        글을 못 고치는 상태가 된다. 그래서 `.doc-body` 만 투명하게 두고
        `.ProseMirror` 가 배치 대상이 된다.
     3. **`vh` 가 전부 무효다.** 이 시트는 창 높이를 읽는 면으로 삼고 쓰였는데
        편집기의 종이는 A4 다. 그대로 두면 표지 하나가 브라우저 창만큼 자리를
        차지한다. 편집기가 `--sheet-h` 로 한 장의 높이를 알려주므로, 화면에서
        종이를 재던 자리는 그 값으로 바꾼다. 인쇄 규칙은 이미 mm 로 적혀 있어
        손대지 않는다. */
  .doc-body { display: contents; }
  .ProseMirror { min-width: 0; cursor: text; }
  /* 제목과 절 제목도 고칠 수 있는 자리다. 서식은 종이처럼 보이므로 표시가
     없으면 읽기 전용으로 읽힌다 — 커서 모양과, 눌렀을 때의 옅은 밑줄. */
  .doc-foot { display: none; }
  [contenteditable="true"] { cursor: text; outline: none; }
  [contenteditable="true"]:focus {
    box-shadow: 0 2px 0 -1px color-mix(in srgb, var(--accent) 45%, transparent);
  }
  .ProseMirror:focus, .ProseMirror-focused { outline: none; }
  /* 빈 절에도 커서를 놓을 자리는 있어야 한다. 문단 하나가 비면 높이가 0 이 되어
     누를 곳이 사라지므로, 비었을 때만 한 줄만큼을 만들어 준다. */
  .ProseMirror > p:only-child:empty::before { content: ''; display: inline-block; height: 1.2em; }
  .ProseMirror img { max-width: 100%; height: auto; }
  /* Tiptap 의 표. 셀 선택 표시와 열 너비 손잡이는 편집 중에만 쓰인다. */
  .tableWrapper { overflow-x: auto; }
  .ProseMirror th, .ProseMirror td { position: relative; }
  .ProseMirror .selectedCell::after {
    content: '';
    position: absolute;
    inset: 0;
    background: color-mix(in srgb, var(--accent) 14%, transparent);
    pointer-events: none;
  }
  .ProseMirror .column-resize-handle {
    position: absolute;
    right: -2px;
    top: 0;
    bottom: 0;
    width: 4px;
    background: var(--accent);
    pointer-events: none;
  }

  /* 종이는 편집기가 뒤에 한 장으로 그린다 — 낱장으로 쪼개던 것을 걷어냈다.
     브라우저에는 쪽을 나누는 방법이 없어서 그 분할은 재고 밀어내는 되먹임이
     될 수밖에 없었고, 수렴하지 않았다. 화면은 이어지는 한 장이고 쪽 경계는
     참고선으로만 그린다. 진짜 분할은 아래 `@media print` 가 한다.

     본문 칸은 그 종이를 가리지 않도록 배경 없이 흐르고, 폭과 높이는 종이에
     맞춘다. */
  /* `.page.paginated`, 후손이 아니라 같은 요소다. 편집기는 두 클래스를 한
     `<div>` 에 붙이므로 `.paginated .page` 는 영원히 맞지 않는다 — 그 형태로
     적어 두었을 때 이 블록 전체가 조용히 무시됐고, 종이 배경과 `100vh` 가
     그대로 남아 낱장 위에 불투명한 판이 한 장 더 깔렸다. */
  .page.paginated {
    background: transparent;
    max-width: none;
    margin: 0;
    min-height: 0;
  }
  .paginated .cover {
    min-height: var(--sheet-h, 1123px);
    padding-top: calc(var(--sheet-h, 1123px) * 0.3);
  }
  .paginated figure img { max-height: calc(var(--sheet-h, 1123px) * 0.5); }

  @media print {
    .ProseMirror .selectedCell::after,
    .ProseMirror .column-resize-handle { display: none; }
  }

  section > .doc-body > .ProseMirror { min-width: 0; }
  /* 편집기에서 각주는 `<section>` 이 아니라 `.ProseMirror` 안에 있다. 그래서
     각주를 발치로 모으는 `order` 와 번호를 세는 counter 를 여기서 한 번 더
     건다 — 세는 자리가 달라지면 번호가 절마다 1 부터 다시 시작한다. */
  .ProseMirror {
    display: flex;
    flex-direction: column;
    counter-reset: note;
  }
  .ProseMirror > small,
  .ProseMirror > figcaption {
    order: 1;
    display: block;
    max-width: 46rem;
    margin: 0;
    padding: 0 0 0 1.4rem;
    text-indent: -1.4rem;
    font-size: 0.83rem;
    line-height: 1.6;
    color: var(--muted);
  }
  .ProseMirror > small { counter-increment: note; }
  .ProseMirror > small::before {
    content: counter(note, footnote-mark) " ";
    color: var(--accent);
    font-weight: 650;
  }
  .ProseMirror > small:first-of-type {
    margin-top: 1.1rem;
    padding-top: 0.6rem;
    border-top: 1px solid var(--hair);
  }
